use serde_json::json;
use wasmi::{Config,Engine,Module,Instance,Store};
fn main() {
 let mut config=Config::default();config.consume_fuel(true);
 let engine=Engine::new(&config);
 let module=Module::new(&engine,include_bytes!("../../../src/foldlitedb/portable_assets/metrics.wasm")).unwrap();
 let mut store=Store::new(&engine,()); store.set_fuel(1_000_000_000).unwrap();
 let instance=Instance::new(&mut store,&module,&[]).unwrap();
 let memory=instance.get_memory(&store,"memory").unwrap();
 let ptr=instance.get_typed_func::<(),i32>(&store,"input_ptr").unwrap().call(&mut store,()).unwrap();
 let payload=json!({"metric":"large","value":1.2345678901234567e-100,"padding":"x".repeat(180)});
 let request=serde_json::to_vec(&json!({"op":"map","documents":vec![payload;1024]})).unwrap();
 memory.write(&mut store,ptr as usize,&request).unwrap();
 let execute=instance.get_typed_func::<i32,i32>(&store,"execute").unwrap();
 let len=execute.call(&mut store,request.len() as i32).unwrap();
 println!("request_bytes={} response_bytes={} fuel_used={}",request.len(),len,1_000_000_000-store.get_fuel().unwrap());
}
